INSERT INTO words (id, simplified, traditional, pinyin, pinyin_numbered, meaning_vi, meaning_en, part_of_speech, hsk_level, stroke_count, frequency_rank, note, created_at, updated_at) VALUES
(151, '吧', '吧', 'ba', 'ba5', 'trợ từ ngữ khí cuối câu: ... nhé, ... đi, ... nhỉ (đề nghị, thúc giục, phỏng đoán)', 'modal particle: suggestion, request or supposition', 'trợ từ', 2, 7, 151, 'Đặt cuối câu để đề nghị hoặc đoán: 我们走吧！(Chúng ta đi thôi!)', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(152, '白', '白', 'bái', 'bai2', 'trắng, màu trắng; (nghĩa mở rộng) uổng công', 'white; in vain', 'tính từ', 2, 5, 152, 'Màu sắc thường nói là 白色 (báisè).', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(153, '百', '百', 'bǎi', 'bai3', 'trăm, một trăm', 'hundred', 'số từ', 2, 6, 153, '100 = 一百, 120 = 一百二十.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(154, '帮助', '幫助', 'bāngzhù', 'bang1zhu4', 'giúp đỡ, sự giúp đỡ', 'to help; help', 'động từ', 2, 16, 154, 'Vừa là động từ vừa là danh từ: 谢谢你的帮助。', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(155, '报纸', '報紙', 'bàozhǐ', 'bao4zhi3', 'báo, tờ báo', 'newspaper', 'danh từ', 2, 15, 155, 'Lượng từ hay dùng: 一份报纸 / 一张报纸.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(156, '比', '比', 'bǐ', 'bi3', 'so, so với (dùng trong câu so sánh)', 'compared to; than', 'giới từ', 2, 4, 156, 'Cấu trúc: A + 比 + B + tính từ. VD: 今天比昨天冷。', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(157, '别', '別', 'bié', 'bie2', 'đừng, chớ; khác, riêng biệt', 'do not; other', 'phó từ', 2, 7, 157, 'Dùng để khuyên can: 别说话！(Đừng nói chuyện!)', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(158, '宾馆', '賓館', 'bīnguǎn', 'bin1guan3', 'khách sạn, nhà khách', 'hotel; guesthouse', 'danh từ', 2, 21, 158, 'Đồng nghĩa gần: 饭店 (fàndiàn) khi chỉ khách sạn.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(159, '长', '長', 'cháng', 'chang2', 'dài (về không gian, thời gian)', 'long', 'tính từ', 2, 4, 159, 'Chữ này còn đọc zhǎng nghĩa là lớn lên, trưởng: 长大.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(160, '唱歌', '唱歌', 'chànggē', 'chang4ge1', 'hát, ca hát', 'to sing (a song)', 'động từ', 2, 25, 160, 'Là cụm động - tân, tách được: 唱一首歌 / 唱歌唱得很好.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(161, '出', '出', 'chū', 'chu1', 'ra, đi ra, ra khỏi', 'to go out; to come out', 'động từ', 2, 5, 161, 'Hay gặp trong 出来, 出去, 出门.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(162, '穿', '穿', 'chuān', 'chuan1', 'mặc, mang, đi (quần áo, giày dép)', 'to wear; to put on', 'động từ', 2, 9, 162, 'Dùng cho quần áo, giày; đội mũ thì dùng 戴.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(163, '次', '次', 'cì', 'ci4', 'lần, lượt (lượng từ chỉ số lần)', 'time; occurrence (measure word)', 'lượng từ', 2, 6, 163, 'Đứng sau động từ: 去过三次 (đã đi ba lần).', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(164, '从', '從', 'cóng', 'cong2', 'từ (chỉ điểm xuất phát về nơi chốn hoặc thời gian)', 'from', 'giới từ', 2, 4, 164, 'Cấu trúc: 从 ... 到 ... (từ ... đến ...).', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(165, '错', '錯', 'cuò', 'cuo4', 'sai, nhầm, lỗi', 'wrong; mistake', 'tính từ', 2, 13, 165, 'Trái nghĩa với 对. Bổ ngữ kết quả: 写错了, 说错了.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(166, '打篮球', '打籃球', 'dǎ lánqiú', 'da3lan2qiu2', 'chơi bóng rổ, đánh bóng rổ', 'to play basketball', 'động từ', 2, 32, 166, 'Các môn dùng tay đi với 打, dùng chân đi với 踢.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(167, '大家', '大家', 'dàjiā', 'da4jia1', 'mọi người, tất cả mọi người', 'everyone; everybody', 'đại từ', 2, 13, 167, 'Hay mở đầu lời chào: 大家好！', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(168, '到', '到', 'dào', 'dao4', 'đến, tới; đến nơi', 'to arrive; to reach', 'động từ', 2, 8, 168, 'Cũng làm bổ ngữ kết quả: 看到, 听到, 买到.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(169, '得', '得', 'de', 'de5', 'trợ từ kết cấu, nối động từ với bổ ngữ trình độ', 'structural particle before a complement of degree', 'trợ từ', 2, 11, 169, 'Cấu trúc: động từ + 得 + tính từ. VD: 说得很好。Chữ này còn đọc děi (phải).', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(170, '等', '等', 'děng', 'deng3', 'đợi, chờ', 'to wait', 'động từ', 2, 12, 170, 'Hay đi với 一下: 等一下 (đợi một chút).', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(171, '弟弟', '弟弟', 'dìdi', 'di4di5', 'em trai', 'younger brother', 'danh từ', 2, 14, 171, 'Âm tiết thứ hai đọc nhẹ (thanh nhẹ).', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(172, '第一', '第一', 'dì yī', 'di4yi1', 'thứ nhất, đầu tiên', 'first; number one', 'số từ', 2, 12, 172, '第 + số = số thứ tự: 第二, 第三 ...', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(173, '懂', '懂', 'dǒng', 'dong3', 'hiểu, hiểu được', 'to understand', 'động từ', 2, 15, 173, 'Thường làm bổ ngữ: 听懂 (nghe hiểu), 看懂 (đọc hiểu).', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(174, '对', '對', 'duì', 'dui4', 'đúng, chính xác; đối với', 'right; correct; toward', 'tính từ', 2, 5, 174, 'Trái nghĩa với 错. Còn làm giới từ: 对我很好。', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(175, '房间', '房間', 'fángjiān', 'fang2jian1', 'căn phòng, phòng', 'room', 'danh từ', 2, 15, 175, 'Lượng từ: 一个房间 / 一间房间.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000');
