(176, '非常', '非常', 'fēicháng', 'fei1chang2', 'vô cùng, rất, hết sức', 'very; extremely', 'phó từ', 2, 19, 176, 'Mức độ mạnh hơn 很: 非常好 (rất tốt).', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(177, '服务员', '服務員', 'fúwùyuán', 'fu2wu4yuan2', 'nhân viên phục vụ, bồi bàn', 'waiter; waitress; attendant', 'danh từ', 2, 20, 177, 'Cách gọi lịch sự trong nhà hàng, khách sạn.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(178, '高', '高', 'gāo', 'gao1', 'cao (chiều cao, mức độ)', 'tall; high', 'tính từ', 2, 10, 178, 'Trái nghĩa: 矮 (thấp về người), 低 (thấp về mức độ).', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(179, '告诉', '告訴', 'gàosu', 'gao4su5', 'nói cho biết, bảo, cho hay', 'to tell; to inform', 'động từ', 2, 14, 179, 'Có hai tân ngữ: 告诉 + người + việc.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
