(181, '给', '給', 'gěi', 'gei3', 'cho, đưa cho; cho, giúp (giới từ)', 'to give; for', 'động từ', 2, 9, 181, 'Làm giới từ: 给我买 (mua cho tôi).', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(182, '公共汽车', '公共汽車', 'gōnggòng qìchē', 'gong1gong4qi4che1', 'xe buýt, xe khách công cộng', 'public bus', 'danh từ', 2, 21, 182, 'Đi xe buýt: 坐公共汽车. Nói tắt là 公交车.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(183, '公司', '公司', 'gōngsī', 'gong1si1', 'công ty', 'company; firm', 'danh từ', 2, 9, 183, 'Lượng từ: 一家公司.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(184, '贵', '貴', 'guì', 'gui4', 'đắt, mắc; quý (cách nói tôn kính)', 'expensive; honorable', 'tính từ', 2, 9, 184, 'Trái nghĩa: 便宜. Hỏi họ lịch sự: 您贵姓？', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(185, '过', '過', 'guò', 'guo4', 'trợ từ chỉ kinh nghiệm: đã từng; động từ: đi qua, trải qua', 'aspect particle for past experience; to pass', 'trợ từ', 2, 6, 185, 'Động từ + 过 = đã từng làm. Phủ định: 没 + động từ + 过.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(186, '还', '還', 'hái', 'hai2', 'còn, vẫn còn; thêm nữa', 'still; yet; also', 'phó từ', 2, 7, 186, 'Chữ này còn đọc huán nghĩa là trả lại.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(187, '孩子', '孩子', 'háizi', 'hai2zi5', 'đứa trẻ, con cái', 'child; children', 'danh từ', 2, 12, 187, 'Chỉ chung con cái trong nhà: 你有几个孩子？', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(188, '好吃', '好吃', 'hǎochī', 'hao3chi1', 'ngon (đồ ăn)', 'tasty; delicious', 'tính từ', 2, 12, 188, 'Đồ uống ngon thì nói 好喝.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(189, '黑', '黑', 'hēi', 'hei1', 'đen, màu đen; tối', 'black; dark', 'tính từ', 2, 12, 189, '天黑了 nghĩa là trời đã tối.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(190, '红', '紅', 'hóng', 'hong2', 'đỏ, màu đỏ', 'red', 'tính từ', 2, 6, 190, 'Màu đỏ tượng trưng cho may mắn trong văn hóa Trung Quốc.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(191, '火车站', '火車站', 'huǒchēzhàn', 'huo3che1zhan4', 'ga tàu hỏa, nhà ga', 'railway station', 'danh từ', 2, 18, 191, '火车 (tàu hỏa) + 站 (ga, bến).', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(192, '机场', '機場', 'jīchǎng', 'ji1chang3', 'sân bay', 'airport', 'danh từ', 2, 12, 192, 'Ra sân bay đón người: 去机场接人.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
