(195, '教室', '教室', 'jiàoshì', 'jiao4shi4', 'phòng học, lớp học', 'classroom', 'danh từ', 2, 20, 195, 'Đọc là jiàoshì, không đọc jiāoshì.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(196, '姐姐', '姐姐', 'jiějie', 'jie3jie5', 'chị gái', 'older sister', 'danh từ', 2, 16, 196, 'Âm tiết thứ hai đọc thanh nhẹ.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(197, '介绍', '介紹', 'jièshào', 'jie4shao4', 'giới thiệu, sự giới thiệu', 'to introduce; introduction', 'động từ', 2, 12, 197, 'Hay dùng: 给大家介绍一下.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(198, '进', '進', 'jìn', 'jin4', 'vào, đi vào, tiến vào', 'to enter; to come in', 'động từ', 2, 7, 198, 'Mời vào nói là 请进！Trái nghĩa: 出.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(199, '近', '近', 'jìn', 'jin4', 'gần, không xa', 'near; close', 'tính từ', 2, 7, 199, 'Đi với 离: A 离 B 很近. Trái nghĩa: 远.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(200, '就', '就', 'jiù', 'jiu4', 'liền, ngay, thì (nhấn mạnh sự việc xảy ra sớm hoặc thuận theo)', 'at once; right away; then', 'phó từ', 2, 12, 200, 'Đứng trước động từ: 我一会儿就来。', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000');
INSERT INTO words (id, simplified, traditional, pinyin, pinyin_numbered, meaning_vi, meaning_en, part_of_speech, hsk_level, stroke_count, frequency_rank, note, created_at, updated_at) VALUES
(201, '觉得', '覺得', 'juéde', 'jue2de5', 'cảm thấy, thấy rằng, cho rằng', 'to feel; to think', 'động từ', 2, 20, 201, 'Theo sau là cả một mệnh đề: 我觉得 + câu.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(202, '咖啡', '咖啡', 'kāfēi', 'ka1fei1', 'cà phê', 'coffee', 'danh từ', 2, 19, 202, 'Từ phiên âm nước ngoài. Lượng từ: 一杯咖啡.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(203, '开始', '開始', 'kāishǐ', 'kai1shi3', 'bắt đầu, khởi đầu', 'to begin; to start', 'động từ', 2, 12, 203, 'Trái nghĩa: 结束. VD: 八点开始上课。', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(204, '考试', '考試', 'kǎoshì', 'kao3shi4', 'thi, kỳ thi, bài kiểm tra', 'to take an exam; examination', 'động từ', 2, 14, 204, 'Vừa là động từ vừa là danh từ: 明天考试 / 一次考试.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(205, '课', '課', 'kè', 'ke4', 'bài học, tiết học, môn học', 'class; lesson', 'danh từ', 2, 10, 205, 'Lên lớp: 上课; tan học: 下课.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(206, '可能', '可能', 'kěnéng', 'ke3neng2', 'có thể, có lẽ, khả năng', 'maybe; possible; possibility', 'phó từ', 2, 15, 206, 'Đứng trước động từ để phỏng đoán: 他可能不来。', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(207, '可以', '可以', 'kěyǐ', 'ke3yi3', 'có thể, được phép', 'can; may; be allowed to', 'động từ', 2, 9, 207, 'Động từ năng nguyện chỉ sự cho phép. Phủ định: 不可以 hoặc 不能.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(208, '快', '快', 'kuài', 'kuai4', 'nhanh; sắp, sắp sửa', 'fast; quick; soon', 'tính từ', 2, 7, 208, 'Cấu trúc 快要 ... 了 nghĩa là sắp ... rồi.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(209, '快乐', '快樂', 'kuàilè', 'kuai4le4', 'vui vẻ, vui sướng, hạnh phúc', 'happy; joyful', 'tính từ', 2, 12, 209, 'Dùng trong lời chúc: 生日快乐, 新年快乐.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(210, '累', '累', 'lèi', 'lei4', 'mệt, mệt mỏi', 'tired; weary', 'tính từ', 2, 11, 210, 'Hay dùng với 很, 太: 太累了！', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(211, '离', '離', 'lí', 'li2', 'cách, rời khỏi (chỉ khoảng cách giữa hai nơi)', 'away from; apart from', 'giới từ', 2, 10, 211, 'Cấu trúc: A 离 B 远 / 近.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(212, '两', '兩', 'liǎng', 'liang3', 'hai (dùng trước lượng từ)', 'two (before a measure word)', 'số từ', 2, 7, 212, 'Đếm số dùng 二, đứng trước lượng từ dùng 两: 两个人.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(213, '零', '零', 'líng', 'ling2', 'số không, lẻ', 'zero', 'số từ', 2, 13, 213, 'Viết tắt trong chữ số là 0: 十点零五分.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(214, '路', '路', 'lù', 'lu4', 'đường, con đường; tuyến (xe)', 'road; route; bus line', 'danh từ', 2, 13, 214, 'Còn dùng cho tuyến xe buýt: 三路车 (xe tuyến số 3).', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(215, '旅游', '旅遊', 'lǚyóu', 'lv3you2', 'du lịch, đi du lịch', 'to travel; tourism', 'động từ', 2, 22, 215, 'Chú ý pinyin có dấu hai chấm trên chữ u: lǚ.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(216, '卖', '賣', 'mài', 'mai4', 'bán', 'to sell', 'động từ', 2, 8, 216, 'Phân biệt với 买 mǎi (mua) - chỉ khác thanh điệu và một nét.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(217, '慢', '慢', 'màn', 'man4', 'chậm', 'slow', 'tính từ', 2, 14, 217, 'Trái nghĩa: 快. Lời chào khi tiễn khách: 慢走。', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(218, '忙', '忙', 'máng', 'mang2', 'bận, bận rộn', 'busy', 'tính từ', 2, 6, 218, 'Hỏi thăm: 你最近忙吗？', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(219, '每', '每', 'měi', 'mei3', 'mỗi, mọi, từng', 'every; each', 'đại từ', 2, 7, 219, 'Thường đi với 都: 每天都 ... (ngày nào cũng ...).', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(220, '妹妹', '妹妹', 'mèimei', 'mei4mei5', 'em gái', 'younger sister', 'danh từ', 2, 16, 220, 'Âm tiết thứ hai đọc thanh nhẹ.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(221, '门', '門', 'mén', 'men2', 'cửa, cửa ra vào', 'door; gate', 'danh từ', 2, 3, 221, 'Ra khỏi nhà: 出门; trước cửa: 门口.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(222, '男', '男', 'nán', 'nan2', 'nam, con trai, giống đực', 'male; man', 'tính từ', 2, 7, 222, 'Ghép từ: 男人, 男孩子, 男同学.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(223, '您', '您', 'nín', 'nin2', 'ngài, ông, bà, quý vị (cách xưng hô tôn kính, lịch sự của 你)', 'you (polite form)', 'đại từ', 2, 11, 223, 'Dùng với người lớn tuổi, thầy cô, khách hàng.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(224, '牛奶', '牛奶', 'niúnǎi', 'niu2nai3', 'sữa bò, sữa tươi', 'milk', 'danh từ', 2, 9, 224, 'Lượng từ: 一杯牛奶.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000'),
(225, '女', '女', 'nǚ', 'nv3', 'nữ, con gái, giống cái', 'female; woman', 'tính từ', 2, 3, 225, 'Ghép từ: 女人, 女孩子, 女儿. Pinyin viết là nǚ.', '2026-01-01 00:00:00.000000', '2026-01-01 00:00:00.000000');
INSERT INTO word_examples (word_id, sentence_zh, sentence_pinyin, sentence_vi, sort_order) VALUES
(151, '我们一起去吃饭吧！', 'Wǒmen yìqǐ qù chīfàn ba!', 'Chúng ta cùng đi ăn cơm nhé!', 0),
(152, '她今天穿了一件白色的衣服。', 'Tā jīntiān chuān le yí jiàn báisè de yīfu.', 'Hôm nay cô ấy mặc một chiếc áo màu trắng.', 0),
(153, '这本书一百二十块钱。', 'Zhè běn shū yìbǎi èrshí kuài qián.', 'Quyển sách này giá một trăm hai mươi tệ.', 0),
(154, '谢谢你帮助我学习汉语。', 'Xièxie nǐ bāngzhù wǒ xuéxí Hànyǔ.', 'Cảm ơn bạn đã giúp tôi học tiếng Hán.', 0),
(155, '爸爸每天早上都看报纸。', 'Bàba měitiān zǎoshang dōu kàn bàozhǐ.', 'Sáng nào bố tôi cũng đọc báo.', 0),
(156, '今天比昨天冷一点儿。', 'Jīntiān bǐ zuótiān lěng yìdiǎnr.', 'Hôm nay lạnh hơn hôm qua một chút.', 0),
(157, '别在教室里说话。', 'Bié zài jiàoshì lǐ shuōhuà.', 'Đừng nói chuyện trong lớp học.', 0),
(158, '我们住在火车站旁边的宾馆。', 'Wǒmen zhù zài huǒchēzhàn pángbiān de bīnguǎn.', 'Chúng tôi ở khách sạn bên cạnh ga tàu hỏa.', 0),
(159, '这条路很长，走路要一个小时。', 'Zhè tiáo lù hěn cháng, zǒulù yào yí ge xiǎoshí.', 'Con đường này rất dài, đi bộ phải mất một tiếng.', 0),
(160, '妹妹唱歌唱得非常好。', 'Mèimei chànggē chàng de fēicháng hǎo.', 'Em gái tôi hát rất hay.', 0),
(161, '他刚出门，你等一下吧。', 'Tā gāng chū mén, nǐ děng yíxià ba.', 'Anh ấy vừa ra ngoài, bạn đợi một chút nhé.', 0),
(162, '天气冷了，你要多穿衣服。', 'Tiānqì lěng le, nǐ yào duō chuān yīfu.', 'Trời lạnh rồi, bạn phải mặc thêm áo.', 0),
(163, '我去过三次中国。', 'Wǒ qù guo sān cì Zhōngguó.', 'Tôi đã đến Trung Quốc ba lần.', 0),
(164, '他从公司到家要坐半个小时的车。', 'Tā cóng gōngsī dào jiā yào zuò bàn ge xiǎoshí de chē.', 'Từ công ty về đến nhà anh ấy phải đi xe nửa tiếng.', 0),
(165, '这个字你写错了。', 'Zhège zì nǐ xiě cuò le.', 'Chữ này bạn viết sai rồi.', 0),
(166, '弟弟每天下午都跟同学打篮球。', 'Dìdi měitiān xiàwǔ dōu gēn tóngxué dǎ lánqiú.', 'Chiều nào em trai tôi cũng chơi bóng rổ với bạn học.', 0),
(167, '大家好，我来介绍一下我的朋友。', 'Dàjiā hǎo, wǒ lái jièshào yíxià wǒ de péngyou.', 'Chào mọi người, tôi xin giới thiệu một chút về bạn của tôi.', 0),
(168, '火车九点到北京。', 'Huǒchē jiǔ diǎn dào Běijīng.', 'Tàu hỏa đến Bắc Kinh lúc chín giờ.', 0),
(169, '他汉语说得很好。', 'Tā Hànyǔ shuō de hěn hǎo.', 'Anh ấy nói tiếng Hán rất giỏi.', 0),
(170, '请在门口等我五分钟。', 'Qǐng zài ménkǒu děng wǒ wǔ fēnzhōng.', 'Xin hãy đợi tôi năm phút ở cửa.', 0),
(171, '我弟弟今年十二岁，在上小学。', 'Wǒ dìdi jīnnián shí''èr suì, zài shàng xiǎoxué.', 'Em trai tôi năm nay mười hai tuổi, đang học tiểu học.', 0),
(172, '这是我第一次坐飞机。', 'Zhè shì wǒ dì-yī cì zuò fēijī.', 'Đây là lần đầu tiên tôi đi máy bay.', 0),
(173, '老师说的话我都听懂了。', 'Lǎoshī shuō de huà wǒ dōu tīng dǒng le.', 'Những lời thầy giáo nói tôi đều nghe hiểu.', 0),
(174, '你说得对，我们明天早上去吧。', 'Nǐ shuō de duì, wǒmen míngtiān zǎoshang qù ba.', 'Bạn nói đúng, sáng mai chúng ta đi nhé.', 0),
(175, '这个房间很大，也很便宜。', 'Zhège fángjiān hěn dà, yě hěn piányi.', 'Căn phòng này rất rộng, mà cũng rất rẻ.', 0),
(176, '我非常喜欢学习汉语。', 'Wǒ fēicháng xǐhuan xuéxí Hànyǔ.', 'Tôi vô cùng thích học tiếng Hán.', 0),
(177, '服务员，请给我一杯咖啡。', 'Fúwùyuán, qǐng gěi wǒ yì bēi kāfēi.', 'Phục vụ ơi, cho tôi một ly cà phê.', 0),
(178, '我哥哥比我高一点儿。', 'Wǒ gēge bǐ wǒ gāo yìdiǎnr.', 'Anh trai tôi cao hơn tôi một chút.', 0),
(179, '请告诉我你什么时候到。', 'Qǐng gàosu wǒ nǐ shénme shíhou dào.', 'Xin cho tôi biết khi nào bạn đến.', 0),
(180, '我哥哥在一家公司工作。', 'Wǒ gēge zài yì jiā gōngsī gōngzuò.', 'Anh trai tôi làm việc ở một công ty.', 0),
(181, '妈妈给我买了一个新手机。', 'Māma gěi wǒ mǎi le yí ge xīn shǒujī.', 'Mẹ mua cho tôi một chiếc điện thoại mới.', 0),
(182, '我每天坐公共汽车去上班。', 'Wǒ měitiān zuò gōnggòng qìchē qù shàngbān.', 'Hằng ngày tôi đi xe buýt đi làm.', 0),
(183, '他们公司离火车站很近。', 'Tāmen gōngsī lí huǒchēzhàn hěn jìn.', 'Công ty của họ rất gần ga tàu hỏa.', 0),
(184, '这件衣服太贵了，有便宜一点儿的吗？', 'Zhè jiàn yīfu tài guì le, yǒu piányi yìdiǎnr de ma?', 'Chiếc áo này đắt quá, có cái nào rẻ hơn một chút không?', 0),
(185, '我没去过中国，但是很想去。', 'Wǒ méi qù guo Zhōngguó, dànshì hěn xiǎng qù.', 'Tôi chưa từng đến Trung Quốc, nhưng rất muốn đi.', 0),
(186, '他还在教室里做作业。', 'Tā hái zài jiàoshì lǐ zuò zuòyè.', 'Cậu ấy vẫn còn đang làm bài tập trong lớp học.', 0),
(187, '他们有两个孩子，一个男孩，一个女孩。', 'Tāmen yǒu liǎng ge háizi, yí ge nánhái, yí ge nǚhái.', 'Họ có hai đứa con, một trai và một gái.', 0),
(188, '妈妈做的鸡蛋面非常好吃。', 'Māma zuò de jīdàn miàn fēicháng hǎochī.', 'Mì trứng mẹ nấu rất ngon.', 0),
(189, '天黑了，我们快回家吧。', 'Tiān hēi le, wǒmen kuài huí jiā ba.', 'Trời tối rồi, chúng ta mau về nhà thôi.', 0),
(190, '她很喜欢那件红色的衣服。', 'Tā hěn xǐhuan nà jiàn hóngsè de yīfu.', 'Cô ấy rất thích chiếc áo màu đỏ kia.', 0),
(191, '请问，去火车站怎么走？', 'Qǐngwèn, qù huǒchēzhàn zěnme zǒu?', 'Xin hỏi, đi đến ga tàu hỏa đi thế nào?', 0),
(192, '从这儿到机场要一个小时。', 'Cóng zhèr dào jīchǎng yào yí ge xiǎoshí.', 'Từ đây đến sân bay mất một tiếng.', 0),
(193, '我每天早上吃两个鸡蛋，喝一杯牛奶。', 'Wǒ měitiān zǎoshang chī liǎng ge jīdàn, hē yì bēi niúnǎi.', 'Mỗi sáng tôi ăn hai quả trứng gà và uống một cốc sữa.', 0),
(194, '我想买两件新衣服。', 'Wǒ xiǎng mǎi liǎng jiàn xīn yīfu.', 'Tôi muốn mua hai chiếc áo mới.', 0),
(195, '我们的教室里有很多学生。', 'Wǒmen de jiàoshì lǐ yǒu hěn duō xuésheng.', 'Trong lớp học của chúng tôi có rất nhiều học sinh.', 0),
(196, '我姐姐是老师，她在中国工作。', 'Wǒ jiějie shì lǎoshī, tā zài Zhōngguó gōngzuò.', 'Chị gái tôi là giáo viên, chị ấy làm việc ở Trung Quốc.', 0),
(197, '我来给大家介绍一下我的新同学。', 'Wǒ lái gěi dàjiā jièshào yíxià wǒ de xīn tóngxué.', 'Tôi xin giới thiệu với mọi người bạn học mới của tôi.', 0),
(198, '请进，外面很冷。', 'Qǐng jìn, wàimiàn hěn lěng.', 'Mời vào, bên ngoài rất lạnh.', 0),
(199, '我家离学校很近，走路十分钟就到了。', 'Wǒ jiā lí xuéxiào hěn jìn, zǒulù shí fēnzhōng jiù dào le.', 'Nhà tôi rất gần trường, đi bộ mười phút là đến.', 0),
(200, '你在这儿等一下，我一会儿就来。', 'Nǐ zài zhèr děng yíxià, wǒ yíhuìr jiù lái.', 'Bạn đợi ở đây một lát, tôi đến ngay.', 0);
INSERT INTO word_examples (word_id, sentence_zh, sentence_pinyin, sentence_vi, sort_order) VALUES
(201, '我觉得这个问题很有意思。', 'Wǒ juéde zhège wèntí hěn yǒu yìsi.', 'Tôi thấy vấn đề này rất thú vị.', 0),
(202, '早上我喜欢喝一杯热咖啡。', 'Zǎoshang wǒ xǐhuan hē yì bēi rè kāfēi.', 'Buổi sáng tôi thích uống một tách cà phê nóng.', 0),
(203, '我们的汉语课八点开始。', 'Wǒmen de Hànyǔ kè bā diǎn kāishǐ.', 'Lớp tiếng Hán của chúng tôi bắt đầu lúc tám giờ.', 0),
(204, '下个星期我们有一次汉语考试。', 'Xià ge xīngqī wǒmen yǒu yí cì Hànyǔ kǎoshì.', 'Tuần sau chúng tôi có một kỳ thi tiếng Hán.', 0),
(205, '今天下午我没有课，可以去运动。', 'Jīntiān xiàwǔ wǒ méiyǒu kè, kěyǐ qù yùndòng.', 'Chiều nay tôi không có tiết học, có thể đi vận động.', 0),
(206, '他今天可能不来上课。', 'Tā jīntiān kěnéng bù lái shàngkè.', 'Hôm nay có thể cậu ấy không đến lớp.', 0),
(207, '这儿的东西很便宜，你可以去看看。', 'Zhèr de dōngxi hěn piányi, nǐ kěyǐ qù kànkan.', 'Đồ ở đây rất rẻ, bạn có thể đi xem thử.', 0),
(208, '快一点儿，公共汽车来了！', 'Kuài yìdiǎnr, gōnggòng qìchē lái le!', 'Nhanh lên một chút, xe buýt đến rồi!', 0),
(209, '祝你生日快乐！', 'Zhù nǐ shēngrì kuàilè!', 'Chúc bạn sinh nhật vui vẻ!', 0),
(210, '今天工作了十个小时，我很累。', 'Jīntiān gōngzuò le shí ge xiǎoshí, wǒ hěn lèi.', 'Hôm nay làm việc mười tiếng, tôi rất mệt.', 0),
(211, '我们学校离机场不远。', 'Wǒmen xuéxiào lí jīchǎng bù yuǎn.', 'Trường chúng tôi cách sân bay không xa.', 0),
(212, '我有两个哥哥，一个姐姐。', 'Wǒ yǒu liǎng ge gēge, yí ge jiějie.', 'Tôi có hai anh trai và một chị gái.', 0),
(213, '现在是十点零五分。', 'Xiànzài shì shí diǎn líng wǔ fēn.', 'Bây giờ là mười giờ năm phút.', 0),
(214, '去宾馆的路我不认识，我们问问吧。', 'Qù bīnguǎn de lù wǒ bú rènshi, wǒmen wènwen ba.', 'Đường đến khách sạn tôi không biết, chúng ta hỏi thử nhé.', 0),
(215, '去年我去中国旅游了两个星期。', 'Qùnián wǒ qù Zhōngguó lǚyóu le liǎng ge xīngqī.', 'Năm ngoái tôi đi du lịch Trung Quốc hai tuần.', 0),
(216, '这儿卖的水果很好吃，也很便宜。', 'Zhèr mài de shuǐguǒ hěn hǎochī, yě hěn piányi.', 'Hoa quả bán ở đây rất ngon và cũng rất rẻ.', 0),
(217, '请你说慢一点儿，我听不懂。', 'Qǐng nǐ shuō màn yìdiǎnr, wǒ tīng bu dǒng.', 'Bạn hãy nói chậm một chút, tôi nghe không hiểu.', 0),
(218, '爸爸这几天工作很忙。', 'Bàba zhè jǐ tiān gōngzuò hěn máng.', 'Mấy hôm nay bố tôi làm việc rất bận.', 0),
(219, '我每天早上六点起床。', 'Wǒ měitiān zǎoshang liù diǎn qǐchuáng.', 'Mỗi ngày tôi thức dậy lúc sáu giờ sáng.', 0),
(220, '我妹妹今年上小学，她很喜欢唱歌。', 'Wǒ mèimei jīnnián shàng xiǎoxué, tā hěn xǐhuan chànggē.', 'Em gái tôi năm nay học tiểu học, em ấy rất thích hát.', 0),
(221, '教室的门开着，里面没有人。', 'Jiàoshì de mén kāi zhe, lǐmiàn méiyǒu rén.', 'Cửa lớp học đang mở, bên trong không có ai.', 0),
(222, '那个男孩子是我弟弟的同学。', 'Nàge nán háizi shì wǒ dìdi de tóngxué.', 'Cậu bé kia là bạn học của em trai tôi.', 0),
(223, '老师，您好！请问您有时间吗？', 'Lǎoshī, nín hǎo! Qǐngwèn nín yǒu shíjiān ma?', 'Thưa thầy, em chào thầy ạ! Xin hỏi thầy có thời gian không ạ?', 0),
(224, '弟弟每天早上都要喝一杯牛奶。', 'Dìdi měitiān zǎoshang dōu yào hē yì bēi niúnǎi.', 'Sáng nào em trai tôi cũng uống một cốc sữa.', 0),
(225, '她是我姐姐的女儿，今年五岁。', 'Tā shì wǒ jiějie de nǚ''ér, jīnnián wǔ suì.', 'Cô bé là con gái của chị gái tôi, năm nay năm tuổi.', 0);
